import { test, expect } from '@playwright/test';

test.describe('Saucedemo login', () => {
  test('AC-1: valid credentials land on the products page', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.locator('#user-name').fill('standard_user');
    await page.locator('#password').fill('secret_sauce');
    await page.locator('#login-button').click();
    await expect(page.locator('.inventory_list')).toBeVisible();
  });

  test('AC-2: the wrong password shows an error', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.locator('#user-name').fill('standard_user');
    await page.locator('#password').fill('definitely_wrong');
    await page.locator('#login-button').click();
    await expect(page.locator('.error-message-container')).toBeVisible();
  });

  test('AC-3: a locked out user is told the account is locked', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.locator('#user-name').fill('locked_out_user');
    await page.locator('#password').fill('secret_sauce');
    await page.locator('#login-button').click();
    await expect(page.locator('.error-message-container')).toBeVisible();
  });
});
